xp=[-100,-80,-60,-40,-20,0,20,40,60,80,100]; fp=[4,8,12,25,32,36,32,25,18,5,3]
def interp(x):
 if x < -100 or x>100: return 0
 for i in range(10):
  if xp[i]<=x<=xp[i+1]:return fp[i]+(fp[i+1]-fp[i])*(x-xp[i])/(xp[i+1]-xp[i])
for pitch in [50,55,60,65,70]:
 v=[sum(interp(o+k*pitch) for k in range(-4,5)) for o in range(pitch)]; print(pitch,min(v),max(v))
